<script setup>
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'
const route=useRoute(), router=useRouter(), demande=ref(null), erreur=ref(''), enCours=ref(false)
const aujourdHui=new Date().toISOString().slice(0,10); const form=ref({ titre:'', date_publication:aujourdHui, date_limite:'', descriptions:'' })
onMounted(async()=>{try{const r=await fetch('/api/offres/a-publier');const list=await r.json();demande.value=list.find(d=>String(d.id)===String(route.params.id));if(!demande.value) throw new Error();form.value.titre=demande.value.poste}catch{erreur.value='Demande introuvable ou non publiable.'}})
async function publier(){enCours.value=true;erreur.value='';try{const r=await fetch('/api/offres',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form.value,id_demande:route.params.id})});const out=await r.json();if(!r.ok)throw new Error(out.message);router.push({name:'offre-publiee',params:{id:out.id}})}catch(e){erreur.value=e.message}finally{enCours.value=false}}
</script>
<template><main class="page"><button class="retour" @click="router.back()">← Retour</button><p v-if="erreur">{{ erreur }}</p><template v-else-if="demande"><h1>Publier une offre</h1><p>Pour {{ demande.poste }} — {{ demande.departement }}</p><form @submit.prevent="publier"><label>Titre<input v-model="form.titre" required></label><label>Date de publication<input v-model="form.date_publication" type="date" required></label><label>Date limite<input v-model="form.date_limite" type="date" required></label><label>Description<textarea v-model="form.descriptions" rows="6"></textarea></label><button :disabled="enCours">{{enCours?'Publication…':'Publier l’offre'}}</button></form></template></main></template>
<style scoped>.page{max-width:650px;margin:auto;padding:24px}.retour{border:0;background:none;color:teal;font-weight:bold;padding:0}.page form{display:grid;gap:14px}.page label{display:grid;gap:6px;font-weight:bold}.page input,.page textarea{padding:10px;border:1px solid #aaa;border-radius:7px;font:inherit}.page form button{background:teal;color:#fff;border:0;border-radius:8px;padding:12px;font-weight:bold}</style>
